custom_css:
/* === 凝固的叹息 感谢代码楼里老师们的代码https://discord.com/channels/1291925535324110879/1380392618336194702
感谢尾老师，类名，输入框伪提示词来自尾老师，hy老师的去除思维链箭头，na老师的悬浮底栏和思维链文字自定义，楼层信息自定义，12老师的去思维链背景色。感谢NA老师的去阴影，感谢咩野老师的去除全局阴影.=== */

/* --- 1. 字体引入 --- */
@import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@400;600&family=Great+Vibes&display=swap'); /* 罗马神圣体 & 古典优雅手写体 */
@import url("https://fontsapi.zeoseven.com/875/main/result.css"); /* 全局中文: ChillHuoSong_F */
@import url("https://fontsapi.zeoseven.com/45/main/result.css");  /* 代码: nzgrRuYinZouZhangKai */
@import url("https://fontsapi.zeoseven.com/502/main/result.css"); /* 引用: PING FANG XIANG SI */
@import url("https://fontsapi.zeoseven.com/7/main/result.css");   /* 标题: Zhuque Fangsong */

/* --- 2. 核心神性颜色与样式变量 --- */
:root {
    --theme-bg-color: #FAFAFA; /* 纯洁汉白玉底色 */
    --theme-bg-mid: #E8ECEF; /* 石雕阴影灰 */
    --card-bg: rgba(255, 255, 255, 0.85); /* 消息面板：半透明白光 */
    --accent-gold: #C5A059; /* 暗雅圣金 */
    --accent-stone: #8B949E; /* 碑文灰 */
    --text-main: #2E3436; /* 深邃灰黑，非纯黑，具有雕刻感 */
    --text-subtle: #737D84; /* 浅雕痕灰 */

    --font-english-script: 'Great Vibes', cursive;
    --font-english-serif: 'Cinzel', serif;
    --font-main: "ChillHuoSong_F", var(--font-english-serif), sans-serif;
    --font-quote: "PING FANG XIANG SI", var(--font-english-script), serif;
    --font-code: "nzgrRuYinZouZhangKai", monospace;
    --font-title: "Zhuque Fangsong (technical preview)", var(--font-english-serif), serif;
}

/* --- 3. 全局样式：去阴影、去边框、大理石神殿背景 --- */
* { box-shadow: none !important; border-style: none !important; }
body { 
    background-color: var(--theme-bg-color) !important; 
    background-image: url('https://images.unsplash.com/photo-1549887552-cb111020d5f2?q=80&w=2070&auto=format&fit=crop'); /* 默认背景：白色神殿大理石雕塑群 */
    background-size: cover;
    background-position: center top;
    background-attachment: fixed;
    color: var(--text-main); 
    font-family: var(--font-main); 
    font-weight: normal; 
}
/* 全局丁达尔神圣光效遮罩层 */
body::after {
    content: ''; position: fixed; top: 0; left: 0; width: 100vw; height: 100vh;
    background: radial-gradient(circle at 50% -20%, rgba(255,255,255,0.7), transparent 70%);
    pointer-events: none; z-index: 9999; mix-blend-mode: soft-light;
}

#sheld, #character_view { background: transparent !important; margin: 0 auto !important; left: 0; right: 0; border: none !important; overflow: visible !important; }
#chat { background: transparent !important; align-items: center !important; padding-bottom: 120px !important; }
h1, h2, h3, h4, .standoutHeader, .inline-drawer-header, .title_restorable { font-family: var(--font-title); color: var(--accent-stone); font-weight: normal; }

/* --- 4. 顶部导航栏 & 抽屉背景 (贴图替换) --- */
#top-settings-holder { position:relative; background-color: rgba(255, 255, 255, 0.5); backdrop-filter: blur(12px); border: none !important; }
.drawer-icon.fa-fw::before { content: '' !important; font-size: 0 !important; }
.drawer-icon.fa-fw { width: 35px; height: 40px; background-size: contain; background-repeat: no-repeat; background-position: center; transition: all 0.5s cubic-bezier(0.4, 0, 0.2, 1); }
.drawer-icon.fa-fw:hover { transform: translateY(-3px) scale(1.05); filter: brightness(1.2) drop-shadow(0 0 5px rgba(255,255,255,0.8)); }

/* 自定义导航栏图标 */
.drawer-icon.fa-sliders, #ai-config-button .drawer-icon, .drawer-icon.fa-font, #advanced-formatting-button .drawer-icon, .drawer-icon.fa-user, #user-settings-button .drawer-icon, .drawer-icon.fa-cubes, #extensions-settings-button .drawer-icon, .drawer-icon.fa-face-smile, #persona-management-button .drawer-icon {
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260501/Kvtw/869X1671/2026-05-01_130629.png/webp'); 
}
.drawer-icon.fa-plug, #sys-settings-button .drawer-icon, .drawer-icon.fa-book-atlas, #WI-SP-button .drawer-icon, .drawer-icon.fa-image, .drawer-icon.fa-panorama, .drawer-icon.fa-bars-progress, #table_database_settings_drawer .drawer-icon, .drawer-icon.fa-address-card, #character_popup_button .drawer-icon {
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260501/IqhP/1511X1469/2026-05-01_130654.png/webp'); 
}

/* 抽屉与弹窗背景图 (神坛祭典) */
.drawer-content, dialog.popup .popup-body, #dialogue_popup {
    background-image: linear-gradient(rgba(255, 255, 255, 0.7), rgba(255, 255, 255, 0.85)), url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260501/qu53/1200X672/21d990f8449232069ada6f049d60e85a_%281%29.jpg/webp') !important;
    background-size: cover; background-position: center;
    border-radius: 8px !important; color: var(--text-main) !important;
}

/* --- 5. 底部悬浮输入栏 (神殿祭坛悬浮版) --- */
#form_sheld { position: absolute !important; bottom: 10px !important; left: 0; right: 0; display: flex; justify-content: center; z-index: 1000; pointer-events: none; }
#send_form { width: 90% !important; max-width: 800px !important; pointer-events: auto; }

#send_form, body.no-blur #send_form { 
    border-radius: 25px !important; 
    background-color: rgba(255, 255, 255, 0.6) !important; 
    padding: 10px 15px !important; 
    backdrop-filter: blur(20px) !important; 
    -webkit-backdrop-filter: blur(20px) !important; 
    border: none !important; 
    box-shadow: none !important; /* 严格遵守无阴影设计 */
    transition: all 0.5s ease !important; 
}

#send_form:hover, body.no-blur #send_form:hover { 
    transform: translateY(-5px); 
    background-color: rgba(255, 255, 255, 0.85) !important; 
}

#rightSendForm, #leftSendForm { gap: 10px; }
#send_textarea { clip-path: none !important; border: none !important; background: transparent !important; color: var(--text-main) !important; font-size: 1rem !important; box-shadow: none !important; }

#nonQRFormItems { position: relative; }
#send_textarea::placeholder { color: transparent !important; text-shadow: none !important; }

/* 完美自适应的伪提示词：使用 left/right 卡住范围，超长自动变成省略号 */
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before { 
    content: 'Carving prayers into the sacred marble... 🏛️'; 
    color: var(--accent-stone); 
    position: absolute; 
    top: 50%; transform: translateY(-50%); 
    left: 50px; right: 70px; 
    text-align: center; 
    font-family: var(--font-english-script); 
    font-size: clamp(1rem, 2.5vw, 1.6rem); 
    pointer-events: none; 
    white-space: nowrap; 
    overflow: hidden; 
    text-overflow: ellipsis;
    opacity: 0.6; 
    animation: oracle-glow 4s infinite alternate;
}
@keyframes oracle-glow { 0% { opacity: 0.3; } 100% { opacity: 0.9; text-shadow: 0 0 8px rgba(197, 160, 89, 0.5); } }

/* 底栏功能按钮贴图 */
#options_button::before, #send_but::before, #send_form #extensionsMenuButton::before, #ai_retry_button::before, #auto_completion_button::before, #mes_impersonate::before { display: none !important; }

#options_button, #send_but, #send_form #extensionsMenuButton, #ai_retry_button, #auto_completion_button, #mes_impersonate { 
    width: 32px; height: 32px; 
    background-size: contain; background-repeat: no-repeat; background-position: center; 
    transition: transform 0.2s ease; font-size: 0; border: none; background-color: transparent; 
}

#options_button:hover, #send_but:hover, #send_form #extensionsMenuButton:hover, #ai_retry_button:hover, #auto_completion_button:hover, #mes_impersonate:hover { 
    transform: scale(1.15) rotate(5deg); 
    filter: drop-shadow(0 0 8px rgba(255,255,255,0.8)); /* 悬浮时散发神性白光，非黑色阴影 */
}

/* 按钮贴图分配 */
#options_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260501/BqHR/1847X1471/2026-05-01_130644.png/webp'); }
#send_form #extensionsMenuButton, #mes_impersonate { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260501/UK7A/1281X1729/2026-05-01_130616.png/webp'); }
#send_but { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260501/adDw/1633X1791/2026-05-01_130817.png/webp'); }
#ai_retry_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260501/BqHR/1847X1471/2026-05-01_130644.png/webp'); filter: sepia(1) hue-rotate(10deg); }
#auto_completion_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260501/UK7A/1281X1729/2026-05-01_130616.png/webp'); filter: sepia(1) hue-rotate(-20deg); }

/* --- 6. 核心：神殿信笺消息框 --- */
.mes { 
    display: flex; flex-direction: column; 
    padding: 0 !important; 
    margin: 100px auto 50px !important; 
    width: 90%; max-width: 800px; 
    background-color: var(--card-bg) !important;

}

/* --- 独立剥离的名字与楼层信息框 (大理石铭牌) --- */
.mes > .ch_name, .mes .mes_block > .ch_name { 
    display: flex !important; position: absolute; 
    top: -200px !important; /* 悬浮在消息框上方 */
    width: max-content !important; /* 宽度自适应内容，不再是100%满框 */
    background: #FFFFFF !important; /* 纯白铭牌 */
    border: 1px solid var(--theme-bg-mid) !important; /* 浅灰色铭牌边框 */
    border-radius: 4px !important;
    padding: 6px 16px !important; 
    z-index: 10;
    align-items: baseline !important;
    gap: 12px !important;
}
/* 与头像对称摆放：头像在左，铭牌在右；头像在右，铭牌在左 */
.mes[is_user="false"] > .ch_name, .mes[is_user="false"] .mes_block > .ch_name { right: 15px !important; left: auto !important; }
.mes[is_user="true"] > .ch_name, .mes[is_user="true"] .mes_block > .ch_name { left: 15px !important; right: auto !important; }

.mes .ch_name > .flex-container { display: flex !important; align-items: baseline !important; gap: 10px !important; }
.mes .ch_name .name_text { font-family: var(--font-english-serif); font-size: 18px !important; letter-spacing: 1px; color: var(--accent-stone) !important; text-transform: uppercase; text-shadow: none !important; }

/* 楼层与时间戳 */
.mes .mesIDDisplay, .mes .mes_timestamp { position: static !important; color: var(--accent-gold) !important; font-size: 12px !important; font-family: var(--font-english-serif); letter-spacing: 1px; margin-left: 5px; }
.mesIDDisplay::before { content: 'Fragment No. '; }
.mesIDDisplay::after { content: ' 🕊️'; }

/* 消息框顶部独立背景横幅 */
.mes .mesAvatarWrapper {
    display: block; padding: 0;
    width: 100%; height: 160px !important; min-height: 160px !important;
    background-size: cover; background-position: center; background-repeat: no-repeat;
    position: relative; z-index: 5; overflow: visible !important;
    border-bottom: 1px solid rgba(197, 160, 89, 0.2);
}
/* AI 横幅 */
.mes[is_user="false"] .mesAvatarWrapper { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260501/iwrL/1200X900/c2987d4f8ee7382a86ef0a13e2b716f7.jpg/webp'); }
/* User 横幅 */
.mes[is_user="true"] .mesAvatarWrapper { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260501/U0xa/1199X808/5832306d805b7947073ea3a2994f8b44.jpg/webp'); }

/* 悬浮神明头像框 */
.mes .avatar {
    position: absolute;
    top: -50px; 
    width: 100px; height: 100px; 
    background: rgba(255, 255, 255, 0.9) !important; 
    padding: 4px !important; 
    z-index: 30; display: flex !important; align-items: center; justify-content: center;
    border-radius: 50% !important; 
    border: 2px solid rgba(255, 255, 255, 0.8) !important;
}
.mes[is_user="false"] .avatar { left: 20px; box-shadow: 0 10px 25px rgba(197, 160, 89, 0.2) !important; }
.mes[is_user="true"] .avatar { right: 20px; left: auto; box-shadow: 0 10px 25px rgba(139, 148, 158, 0.2) !important; }
.mes .avatar img { 
    width: 100% !important; height: 100% !important; 
    object-fit: cover !important; border-radius: 50% !important; 
}

/* --- 贴图 (大幅缩小并垫底，不挡文字) --- */
/* AI贴图在右下角 */
.mes[is_user="false"] .mes_block::before {
    content: ''; position: absolute; bottom: -15px; right: -15px;
    width: 110px; height: 110px; /* 缩小尺寸 */
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260501/pOvk/1309X1924/2026-05-01_130719.png/webp');
    background-size: contain; background-repeat: no-repeat; background-position: bottom right;
    z-index: 0 !important; pointer-events: none; opacity: 1; /* 降低透明度并强制置底 */
    animation: holy-float-right 6s infinite ease-in-out alternate;
}
/* 用户贴图在左下角 */
.mes[is_user="true"] .mes_block::before {
    content: ''; position: absolute; bottom: -15px; left: -15px;
    width: 110px; height: 110px; /* 缩小尺寸 */
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260501/eySi/1729X1436/2026-05-01_130801.png/webp');
    background-size: contain; background-repeat: no-repeat; background-position: bottom left;
    z-index: 0 !important; pointer-events: none; opacity: 1; /* 降低透明度并强制置底 */
    animation: holy-float-left 5s infinite ease-in-out alternate-reverse;
}
@keyframes holy-float-right { 0% { transform: translateY(0) rotate(0deg); } 100% { transform: translateY(-5px) rotate(2deg); } }
@keyframes holy-float-left { 0% { transform: translateY(0) rotate(0deg); } 100% { transform: translateY(-5px) rotate(-2deg); } }

/* 消息主体区文字 (强制提升层级防遮挡) */
.mes .mes_block { background-color: transparent !important; background-image: none !important; padding: 40px 40px 50px 40px !important; position: relative; border: none !important; overflow: visible !important; min-height: 120px !important; z-index: 10; }
.mes .mes_text, .mes_reasoning { background: transparent !important; border: none !important; padding: 0 !important; margin: 0 !important; backdrop-filter: none !important; position: relative; z-index: 10 !important; /* 强制层级在贴纸上方 */ }

/* 背景隐约的圣殿拉丁文水印 */
.mes_block::after {
    content: 'ROMA AETERNA \A DIVINE ECHOES'; white-space: pre;
    position: absolute; top: 30px; color: rgba(139, 148, 158, 0.08);
    font-family: var(--font-english-serif); font-size: 32px; text-align: center; font-weight: bold; letter-spacing: 4px;
    z-index: 0; pointer-events: none; user-select: none;
}
.mes[is_user="false"] .mes_block::after { left: 40px; }
.mes[is_user="true"] .mes_block::after { right: 40px; }

/* 思维链自定义 (倾听神谕) */
#chat .mes .mes_reasoning_header { background: transparent !important; border: none !important; border-radius: 0; backdrop-filter: none !important; padding: 0 !important; margin-bottom: 15px !important; display: inline-flex !important; align-items: center !important; }
.mes_reasoning_arrow { display: none !important; }
.mes_reasoning_header h4, .mes_reasoning_header_title { font-size: 0 !important; visibility: hidden; }
.mes_reasoning_header h4::before, .mes_reasoning_header_title::before { 
    content: "🕊️ Listening to the Oracle... (Divining)"; 
    font-family: var(--font-english-script); font-size: 26px !important; 
    color: var(--accent-gold); visibility: visible; letter-spacing: 1px; 
}
.mes_reasoning { padding-left: 20px !important; margin-bottom: 30px !important; color: var(--text-subtle); font-family: var(--font-quote); font-size: 1.05em; position: relative; }
.mes_reasoning::before { 
    content: ''; position: absolute; left: 0; top: 5px; bottom: 5px; width: 2px; 
    background: linear-gradient(to bottom, transparent, var(--accent-gold), transparent);
}
.mes .mes_text { line-height: 2.3; color: var(--text-main); font-size: 16px; text-align: justify; letter-spacing: 0.5px; }

/* 编辑按钮悬浮设计 */
.mes .mes_buttons, .mes .mes_edit_buttons { flex-direction: row-reverse; gap: 8px; opacity: 0; transition: opacity 0.4s ease; pointer-events: auto !important; margin-top: 15px; position: relative; z-index: 15; }
.mes:hover .mes_buttons, .mes:hover .mes_edit_buttons { opacity: 1; }
.mes .mes_buttons .mes_button, .mes .mes_edit_buttons .mes_button { background-color: rgba(255, 255, 255, 0.9) !important; color: var(--accent-stone) !important; padding: 6px !important; border-radius: 50% !important; cursor: pointer; transition: all 0.3s ease; font-size: 14px !important; border: 1px solid rgba(139, 148, 158, 0.2) !important; }
.mes .mes_buttons .mes_button:hover, .mes .mes_edit_buttons .mes_button:hover { background-color: var(--accent-gold) !important; color: #fff !important; transform: scale(1.1) rotate(15deg); border-color: transparent !important; }

/* 打字指示器 (神石发光) */
#typing_indicator { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260501/adDw/1633X1791/2026-05-01_130817.png/webp') !important; background-size: contain !important; background-repeat: no-repeat !important; background-position: center !important; animation: holy-breathe 2s infinite ease-in-out, oracle-glow 2s infinite alternate; border: none !important; height: 50px !important; width: 50px !important; margin: 15px auto !important; }
#typing_indicator .dot { display: none !important; }

/* --- 全局UI设定 (洁白、无阴影) --- */
.standoutHeader, .inline-drawer-header, .title_restorable, #extensions_settings2 > div, #extensions_settings > div, .openai_logit_bias_preset_form, details > summary, #power-user-options-block h4, #InstructSettingsColumn h4, #SystemPromptColumn h4, #ContextSettings h4, .persona_management_global_settings h4, #character_popup h4, #AdvancedFormatting h4, #rm_group_chats_block h4, div[name*='HandlingToggles'] h4, div[name*='MiscellaneousToggles'] h4 { background: rgba(255, 255, 255, 0.6) !important; border-radius: 4px !important; padding: 12px 18px !important; margin-bottom: 10px !important; color: var(--text-main) !important; }
input[type="text"], input[type="number"], input[type="search"], textarea, select, .text_pole { background-color: rgba(255,255,255,0.7) !important; color: var(--text-main) !important; border-radius: 4px !important; padding: 10px !important; border: 1px solid rgba(139, 148, 158, 0.2) !important; font-family: var(--font-english-serif); }
input:focus, textarea:focus, select:focus { outline: none !important; background-color: rgba(255,255,255,1) !important; border: 1px solid var(--accent-gold) !important; }
.menu_button { background-color: rgba(255, 255, 255, 0.6) !important; color: var(--accent-stone) !important; transition: all 0.4s ease; border-radius: 4px !important; }
.menu_button:hover { background-color: var(--accent-stone) !important; color: white !important; }
input[type="checkbox"]:checked::before { box-shadow: inset 1em 1em var(--accent-gold) !important; }

dialog.popup { background-color: transparent !important; }
dialog.popup .popup-body::before, #dialogue_popup::before { content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0; background-color: rgba(255, 255, 255, 0.88); z-index: 0; border-radius: 8px; }
dialog.popup .popup-body > *, #dialogue_popup > * { position: relative; z-index: 1; }
.menu_button.active, .menu_button.world_set, .menu_button.fav_on, #left-nav-panel .menu_button.selected { background-color: var(--accent-gold) !important; color: #fff !important; letter-spacing: 1px; }

/* 手机端适配调整 */
@media (max-width: 768px) {
    .mes { margin: 80px auto 40px !important; border-width: 5px !important; }
    .mes > .ch_name, .mes .mes_block > .ch_name { top: -170px !important; padding: 4px 12px !important; }
    .mes .ch_name .name_text { font-size: 15px !important; }
    .mes .mesIDDisplay, .mes .mes_timer { font-size: 10px !important; }
    .mes[is_user="false"] .mes_block::before, .mes[is_user="true"] .mes_block::before { width: 70px; height: 70px; bottom: -10px; } 
    .mes[is_user="false"] .mes_block::before { right: -10px; }
    .mes[is_user="true"] .mes_block::before { left: -10px; }
    .mes .avatar { width: 80px; height: 80px; top: -40px; }
    .mes .mesAvatarWrapper { height: 120px !important; min-height: 120px !important; }
    .mes_block::after { font-size: 22px; }
}

#dialogue_popup { z-index: 10000 !important; pointer-events: auto !important; }
#dialogue_del_mes_ok, #dialogue_del_mes_cancel { background-color: rgba(255,255,255,0.9) !important; color: var(--accent-stone) !important; border-radius: 4px !important; padding: 12px 24px !important; margin: 10px 8px !important; transition: all 0.4s ease !important; border: 1px solid rgba(139, 148, 158, 0.2) !important; }
#dialogue_del_mes_ok:hover { background-color: var(--accent-gold) !important; color: #fff !important; transform: translateY(-2px) !important; border-color: transparent !important; }
#dialogue_del_mes_cancel:hover { background-color: var(--accent-stone) !important; color: #fff !important; transform: translateY(-2px) !important; border-color: transparent !important; }

/* 楼层/时间戳：居中悬浮于消息框之上，作为独立的“大理石碎片” */
.mes .mesIDDisplay, .mes .mes_timer {
    position: absolute !important;
    top: -80px !important; /* 定位在头像上方 */
    left: 50% !important;
    transform: translateX(-50%) !important;
    display: flex !important;
    align-items: center !important;
    gap: 10px !important;
    background-color: rgba(255, 255, 255, 0.95) !important;
    padding: 4px 12px !important;
    border-radius: 12px !important;
    border: 1px solid var(--theme-bg-mid) !important;
    z-index: 40 !important; /* 层级最高，确保可见 */
    color: var(--accent-gold) !important; 
    font-size: 11px !important; 
    font-family: var(--font-english-serif) !important; 
    letter-spacing: 1px !important; 
    white-space: nowrap; /* 防止换行 */
}

.mesIDDisplay::before { content: 'Fragment No. '; }
.mesIDDisplay::after { content: ' 🕊️'; }
